package dev.zyon.bootstrap;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.jar.*;
import org.objectweb.asm.*;import org.objectweb.asm.commons.*;import org.objectweb.asm.tree.*;
/** Builds a local derivative from the user's verified vanilla archive. No Minecraft code is distributed. */
public final class PatchMain {
 static final String HOOK="dev/zyon/platform/Hooks";
 public static void main(String[] args)throws Exception{
  if(args.length!=2)throw new IllegalArgumentException("Expected vanilla input and local output paths");
  final Map<String,String> classes=new HashMap<String,String>(),fields=new HashMap<String,String>(),methods=new HashMap<String,String>();
  InputStream map=PatchMain.class.getResourceAsStream("/zyon-engine/mappings.tsv");if(map==null)throw new IOException("Missing engine mappings");
  try(BufferedReader r=new BufferedReader(new InputStreamReader(map,"UTF-8"))){String s;while((s=r.readLine())!=null){String[] p=s.split("\t");if(p[0].equals("C"))classes.put(p[1],p[2]);else if(p[0].equals("F"))fields.put(p[1]+"/"+p[2],p[3]);else methods.put(p[1]+"/"+p[2]+p[3],p[4]);}}
  final Map<String,List<String>> parents=new HashMap<String,List<String>>();final Map<String,byte[]> data=new LinkedHashMap<String,byte[]>();
  try(JarFile in=new JarFile(args[0])){Enumeration<JarEntry> it=in.entries();while(it.hasMoreElements()){JarEntry e=it.nextElement();if(e.isDirectory()||e.getName().startsWith("META-INF/"))continue;byte[] bytes=read(in.getInputStream(e));data.put(e.getName(),bytes);if(e.getName().endsWith(".class")){ClassReader cr=new ClassReader(bytes);List<String> ps=new ArrayList<String>();if(cr.getSuperName()!=null)ps.add(cr.getSuperName());ps.addAll(Arrays.asList(cr.getInterfaces()));parents.put(cr.getClassName(),ps);}}}
  Remapper remap=new Remapper(){public String map(String n){String r=classes.get(n);return r==null?n:r;}
   String inherited(Map<String,String> names,String owner,String suffix,Set<String> seen){if(!seen.add(owner))return null;String r=names.get(owner+"/"+suffix);if(r!=null)return r;List<String> ps=parents.get(owner);if(ps!=null)for(String p:ps){r=inherited(names,p,suffix,seen);if(r!=null)return r;}return null;}
   public String mapFieldName(String owner,String name,String desc){String r=inherited(fields,owner,name,new HashSet<String>());return r==null?name:r;}
   public String mapMethodName(String owner,String name,String desc){if(name.charAt(0)=='<')return name;String r=inherited(methods,owner,name+desc,new HashSet<String>());return r==null?name:r;}
  };
  Path out=Paths.get(args[1]),temp=out.resolveSibling(out.getFileName()+".preparing");Files.createDirectories(out.toAbsolutePath().getParent());Set<String> hooks=new TreeSet<String>();
  try(JarOutputStream jar=new JarOutputStream(Files.newOutputStream(temp))){for(Map.Entry<String,byte[]> e:data.entrySet()){String name=e.getKey();byte[] bytes=e.getValue();if(name.endsWith(".class")){ClassNode node=new ClassNode();new ClassReader(bytes).accept(new ClassRemapper(node,remap),0);patch(node,hooks);ClassWriter writer=new ClassWriter(ClassWriter.COMPUTE_MAXS);node.accept(writer);bytes=writer.toByteArray();name=node.name+".class";}JarEntry entry=new JarEntry(name);entry.setTime(0);jar.putNextEntry(entry);jar.write(bytes);jar.closeEntry();}}
  for(String required:Arrays.asList("resources","gui","tick","keyboard","mouse","overlay","fov","player","names","highlight","drawGui","guiInit","guiMouse","guiAction","chat","brand","worldLast","cape"))if(!hooks.contains(required)){Files.deleteIfExists(temp);throw new IOException("Missing vanilla integration: "+required+" / "+hooks);}
  Files.move(temp,out,StandardCopyOption.REPLACE_EXISTING);System.out.println("ZYON_ENGINE_PREPARED "+hooks);
 }
 static byte[] read(InputStream in)throws IOException{try(InputStream s=in;ByteArrayOutputStream b=new ByteArrayOutputStream()){byte[] data=new byte[16384];int n;while((n=s.read(data))!=-1)b.write(data,0,n);return b.toByteArray();}}
 static MethodInsnNode call(String name,String desc){return new MethodInsnNode(Opcodes.INVOKESTATIC,HOOK,name,desc,false);}
 static void guard(MethodNode m,InsnList condition){LabelNode resume=new LabelNode();condition.add(new JumpInsnNode(Opcodes.IFEQ,resume));condition.add(new InsnNode(Opcodes.RETURN));condition.add(resume);condition.add(new FrameNode(Opcodes.F_SAME,0,null,0,null));m.instructions.insert(condition);}
 static void patch(ClassNode c,Set<String> seen){for(MethodNode m:c.methods){String n=c.name,name=m.name,d=m.desc;
  if(n.equals("net/minecraft/client/entity/AbstractClientPlayer")&&name.equals("getLocationCape")){for(AbstractInsnNode i:m.instructions.toArray())if(i.getOpcode()==Opcodes.ARETURN){InsnList x=new InsnList();x.add(new VarInsnNode(Opcodes.ALOAD,0));x.add(call("cape","(Lnet/minecraft/util/ResourceLocation;Lnet/minecraft/client/entity/AbstractClientPlayer;)Lnet/minecraft/util/ResourceLocation;"));m.instructions.insertBefore(i,x);}seen.add("cape");}
  if(n.equals("net/minecraft/client/renderer/EntityRenderer")&&name.equals("renderWorldPass")){for(AbstractInsnNode i:m.instructions.toArray())if(i.getOpcode()==Opcodes.RETURN){InsnList x=new InsnList();x.add(new VarInsnNode(Opcodes.FLOAD,2));x.add(call("worldLast","(F)V"));m.instructions.insertBefore(i,x);}seen.add("worldLast");}
  if(n.equals("net/minecraft/client/renderer/OpenGlHelper")&&name.equals("setLightmapTextureCoords")){InsnList x=new InsnList();x.add(new VarInsnNode(Opcodes.ILOAD,0));x.add(new VarInsnNode(Opcodes.FLOAD,1));x.add(new VarInsnNode(Opcodes.FLOAD,2));x.add(call("lightmap","(IFF)V"));m.instructions.insert(x);}
  if(n.equals("net/minecraft/client/Minecraft")&&name.equals("displayGuiScreen")){InsnList x=new InsnList();x.add(new VarInsnNode(Opcodes.ALOAD,1));x.add(call("guiOpen","(Lnet/minecraft/client/gui/GuiScreen;)Lnet/minecraft/client/gui/GuiScreen;"));x.add(new VarInsnNode(Opcodes.ASTORE,1));m.instructions.insert(x);seen.add("gui");}
  if(n.equals("net/minecraft/client/Minecraft")&&name.equals("runTick")){m.instructions.insert(call("tickStart","()V"));for(AbstractInsnNode i:m.instructions.toArray())if(i.getOpcode()==Opcodes.RETURN)m.instructions.insertBefore(i,call("tickEnd","()V"));seen.add("tick");}
  if(n.equals("net/minecraft/client/gui/GuiIngame")&&name.equals("renderGameOverlay")){m.instructions.insert(call("overlayPre","()V"));for(AbstractInsnNode i:m.instructions.toArray())if(i.getOpcode()==Opcodes.RETURN){InsnList x=new InsnList();x.add(new VarInsnNode(Opcodes.FLOAD,1));x.add(call("overlayPost","(F)V"));m.instructions.insertBefore(i,x);}seen.add("overlay");}
  if(n.equals("net/minecraft/client/gui/GuiIngame")&&name.equals("showCrosshair"))for(AbstractInsnNode i:m.instructions.toArray())if(i.getOpcode()==Opcodes.IRETURN)m.instructions.insertBefore(i,call("crosshair","(Z)Z"));
  if(n.equals("net/minecraft/client/renderer/EntityRenderer")&&name.equals("getFOVModifier")){for(AbstractInsnNode i:m.instructions.toArray())if(i.getOpcode()==Opcodes.FRETURN)m.instructions.insertBefore(i,call("fov","(F)F"));seen.add("fov");}
  if(n.equals("net/minecraft/client/renderer/entity/RenderPlayer")&&name.equals("doRender")&&d.startsWith("(Lnet/minecraft/client/entity/AbstractClientPlayer;")){for(AbstractInsnNode i:m.instructions.toArray())if(i.getOpcode()==Opcodes.RETURN){InsnList x=new InsnList();x.add(new VarInsnNode(Opcodes.ALOAD,1));x.add(new VarInsnNode(Opcodes.DLOAD,2));x.add(new VarInsnNode(Opcodes.DLOAD,4));x.add(new VarInsnNode(Opcodes.DLOAD,6));x.add(new VarInsnNode(Opcodes.FLOAD,9));x.add(call("playerPost","(Lnet/minecraft/entity/player/EntityPlayer;DDDF)V"));m.instructions.insertBefore(i,x);}seen.add("player");}
  if(n.equals("net/minecraft/client/renderer/entity/RendererLivingEntity")&&name.equals("renderName")&&d.startsWith("(Lnet/minecraft/entity/EntityLivingBase;")){InsnList x=new InsnList();x.add(new VarInsnNode(Opcodes.ALOAD,1));x.add(call("hideName","(Lnet/minecraft/entity/EntityLivingBase;)Z"));guard(m,x);seen.add("names");}
  if(n.equals("net/minecraft/client/renderer/RenderGlobal")&&name.equals("drawSelectionBox")){InsnList x=new InsnList();x.add(new VarInsnNode(Opcodes.ALOAD,1));x.add(new VarInsnNode(Opcodes.ALOAD,2));x.add(new VarInsnNode(Opcodes.ILOAD,3));x.add(new VarInsnNode(Opcodes.FLOAD,4));x.add(call("highlight","(Lnet/minecraft/entity/player/EntityPlayer;Lnet/minecraft/util/MovingObjectPosition;IF)Z"));guard(m,x);seen.add("highlight");}
  if(n.equals("net/minecraft/client/gui/GuiScreen")&&name.equals("setWorldAndResolution")){for(AbstractInsnNode i:m.instructions.toArray())if(i.getOpcode()==Opcodes.RETURN){InsnList x=new InsnList();x.add(new VarInsnNode(Opcodes.ALOAD,0));x.add(call("guiInit","(Lnet/minecraft/client/gui/GuiScreen;)V"));m.instructions.insertBefore(i,x);}seen.add("guiInit");}
  if(n.equals("net/minecraft/client/gui/GuiScreen")&&name.equals("handleMouseInput")){InsnList x=new InsnList();x.add(new VarInsnNode(Opcodes.ALOAD,0));x.add(call("guiMouse","(Lnet/minecraft/client/gui/GuiScreen;)Z"));guard(m,x);seen.add("guiMouse");}
  if(n.equals("net/minecraft/client/gui/GuiScreen")&&name.equals("sendChatMessage")&&d.equals("(Ljava/lang/String;Z)V")){InsnList x=new InsnList();x.add(new VarInsnNode(Opcodes.ALOAD,1));x.add(new VarInsnNode(Opcodes.ILOAD,2));x.add(call("chat","(Ljava/lang/String;Z)Z"));guard(m,x);seen.add("chat");}
  if(n.equals("net/minecraft/client/ClientBrandRetriever")&&name.equals("getClientModName")){m.instructions.clear();m.tryCatchBlocks.clear();if(m.localVariables!=null)m.localVariables.clear();m.instructions.add(new LdcInsnNode("ZyonClient"));m.instructions.add(new InsnNode(Opcodes.ARETURN));seen.add("brand");}
  for(AbstractInsnNode i:m.instructions.toArray())if(i instanceof MethodInsnNode){MethodInsnNode v=(MethodInsnNode)i;
   if(v.owner.equals("net/minecraft/client/Minecraft")&&v.name.equals("refreshResources")&&n.equals("net/minecraft/client/Minecraft")&&name.equals("startGame")){m.instructions.insertBefore(i,call("resources","()V"));seen.add("resources");}
   if(v.owner.equals("org/lwjgl/input/Keyboard")&&v.name.equals("next")){v.owner=HOOK;v.name="keyboardNext";seen.add("keyboard");}
   if(v.owner.equals("org/lwjgl/input/Mouse")&&v.name.equals("next")){v.owner=HOOK;v.name="mouseNext";seen.add("mouse");}
   if(v.owner.equals("net/minecraft/client/gui/GuiScreen")&&v.name.equals("drawScreen")&&n.equals("net/minecraft/client/renderer/EntityRenderer")){v.setOpcode(Opcodes.INVOKESTATIC);v.owner=HOOK;v.name="drawGui";v.desc="(Lnet/minecraft/client/gui/GuiScreen;IIF)V";seen.add("drawGui");}
   if(v.owner.equals("net/minecraft/client/gui/GuiScreen")&&v.name.equals("actionPerformed")&&n.equals("net/minecraft/client/gui/GuiScreen")){v.setOpcode(Opcodes.INVOKESTATIC);v.owner=HOOK;v.name="guiAction";v.desc="(Lnet/minecraft/client/gui/GuiScreen;Lnet/minecraft/client/gui/GuiButton;)V";seen.add("guiAction");}
   if(v.owner.equals("net/minecraft/client/renderer/EntityRenderer")&&v.name.equals("updateCameraAndRender")&&n.equals("net/minecraft/client/Minecraft")){m.instructions.insertBefore(i,call("renderStart","()V"));m.instructions.insert(i,call("renderEnd","()V"));}
  }
 }}
}
